T[] SFILTER (T[] array, condition){
    int count = 0;
    for (int i = 0; i < array.length; i++)
        if (condition(array[i]))
            count++;
    T[] selectedPoints = new T[count];
    int i = 0;
    int j = 0;
    while (j < count){
        if (condition(array[i]))
            selectedPoints[j++] = array[i];
        i++;
    }
    return selectedPoints;
}

class Set<T>{
    private T[] elements;
    public Set (T[] elements){
        this.elements = COPYARR(elements);
    }
    public String toString (){
        return STRARR(this.elements);
    }

    public boolean contains (T element){
        return FIND(this.elements, this.elements[i] == element) < this.elements.length;
    }

	public boolean add(T element){
	    FAIL(contains(element), throw new IllegalStateException(element + " already is in the set"));
		SAPPEND(this.element, element);
	}

	public void remove (T element) throws java.util.NoSuchElementElementException{
        int pos = FIND(this.elements, this.elements[i] == element) throw new java.util.NoSuchElementElementException (element + " not present");
        elements = SREMOVE(this.elements, pos);
    }

	public Set intersection(Set<T> set){
	    return REDUCE(elements, new Set<T>(), if (set.contains(elements[i]) accumulator.add(elements[i]));
	}

	public Set union(Set<T> set){
	    Set<T> unionSet = COPYARR(elements);
	    return REDUCE(set.elements, unionSet, if (!unionSet.contains(set.elements[i]) unionSet.add(elements[i]));
	}
}

class MutableString{
    private static DATACLASS(Node(+char ch, [+Node next]))
    private int numberOfChars = 0;
    private Node first = null;
    public MutableString (char[] chars){
        LCOPYARR(first, chars);
    }
    public String toString (){
        return LSTRARR(first);
    }
    public char charAt (int index) throws java.lang.IndexOutOfBoundsException{
	    FAIL(OUTRANGE[0, index, numberOfChars-1], java.lang.IndexOutOfBoundsException)
		return LACCESS(first, index);
	}
    public void addFirst (char ch){
	    LINSERT(first, 0, char);
		numberOfChars++;
	}
}

class MappingRelationship{
    private static DATACLASS(Relationship(+T key, +T value) -> (key + " -->" + value))
    private Relationship[] relationships;
    public Dictionary (){
        relationships = new Relationship[0];
    }

    public String toString (){
        String s = "";
        for (int i = 0; i < relationships.length; i++)
            s = s + relationships[i] + "\n";
        return s;
    }

    public void addRelationship (String key, String value){
        relationship = SAPPEND<Relationship>(relationships, new Relationship(key, value));
    }

    public String get(String key) throws IllegalArgumentException{
        int i = FIND(relationships, relationships[i].key.equals(key)) throw new IllegalArgumentException ("word not found: " + key);
        return relationship[i].value;
    }
}

import java.io.*;    // FileReader, BufferedReader, PrintWriter,
                     // IOException

class SynonymHandler{
    public static String[] readSynonymData (String synonymFile) throws IOException{
        BufferedReader reader = new BufferedReader(
	        new FileReader(synonymFile));
        int numberOfLines = 0;
        String synonymLine = reader.readLine();
        while (synonymLine != null)
        {
			numberOfLines++;
			synonymLine = reader.readLine();
		}
		reader.close();

		String[] synonymData = new String[numberOfLines];
        reader = new BufferedReader(new FileReader(synonymFile));
		for (int i = 0; i < numberOfLines; i++)
		    synonymData[i] = reader.readLine();
		reader.close();

		return synonymData;
    }

    public static void writeSynonymData (String[] synonymData, String synonymFile) throws IOException {
        PrintWriter writer = new PrintWriter(synonymFile);
        for (String synonymLine : synonymData)
            writer.println(synonymLine);
        writer.close();

    }

	private static int synonymLineIndex(String[] synonymData, String word) throws IllegalArgumentException{
        return FIND(synonymData, (i) -> {
            int d = synonymData[i].indexOf('|');
            String w = synonymData[i].substring(0, d).trim();
            return w.equalsIgnoreCase(word);
        });
    }

    public static String getSynonymLine (String[] synonymData, String word) throws IllegalArgumentException -> synonymLineIndex(synonymData, word)
    public static String[] addSynonymLine(String[] data, String line) -> SAPPEND(data, line);
	static String[] removeSynonymLine(String[] data, String word) throws IllegalArgumentException -> SREMOVE(data, synonymLineIndex(data, word))


	private static String[] getSynonyms (String synonymLine){
        String[] synonymLineParts = synonymLine.split("\\|");
        return synonymLineParts[1].trim().split(", ");
	}

    public static void addSynonym(String[] data, String word, String synonym) FAIL IllegalArgumentException{
        int index = synonymLineIndex(data, word);
        String[] syns = getSynonyms(data[index]);

        syns = SAPPEND(syns, synonym);

        String name = data[index].split("\\|")[0].trim();
        data[index] = name + " | " + String.join(", ", syns);
    }


    static void removeSynonym(String[] data, String word, String synonym) throws IllegalArgumentException, IllegalStateException{
        int index = synonymLineIndex(data, word);
        String[] syns = getSynonyms(data[index]);

        if (syns.length <= 1)
            FAIL IllegalStateException;

        // Use SFILTER to remove the unwanted synonym
        String[] newSyns = SFILTER(syns,
            (s) -> !s.equalsIgnoreCase(synonym)
        );

        String name = data[index].split("\\|")[0].trim();
        data[index] = name + " | " + String.join(", ", newSyns);
    }


    private static void sortIgnoreCase (String[] strings){
        SelectionSort.selectionSort(strings, (String string1, String string2) -> string1.compareTo(string2));
	}

    private static String sortSynonymLine (String synonymLine){
        String[] synonymLineParts = synonymLine.split("\\|");
        String name = synonymLineParts[0].trim();
        String[] synonyms = synonymLineParts[1].trim().split(", ");
        sortIgnoreCase(synonyms);
        return String.format("%s | %s", name, String.join(", ", synonyms));
	}

	public static void sortSynonymData (String[] synonymData){
        sortIgnoreCase(synonymData);
        for (int i = 0; i < synonymData.length; i++){
            synonymData[i] = sortSynonymLine(synonymData[i]);
        }
	}

}

