private String formatString (String str, boolean isPrefix) {
    return (str.isBlank() || str.isEmpty()) ? "" : isPrefix ? " " + str : str + " ";
}
private String preOrderTraversal(TreeNode<?> parentNode) {
    if (parentNode == null)
        return "";
    return parentNode.getVal() + formatString(preOrderTraversal(parentNode.getLeft()), true) + formatString(preOrderTraversal(parentNode.getRight()), true);
}

private String inOrderTraversal(TreeNode<?> parentNode) {
    if (parentNode == null)
        return "";
    return formatString(inOrderTraversal(parentNode.getLeft()), false) + parentNode.getVal().toString() + formatString(inOrderTraversal(parentNode.getRight()), true);
}

private String postOrderTraversal(TreeNode<?> parentNode) {
    if (parentNode == null)
        return "";
    return formatString(postOrderTraversal(parentNode.getLeft()), false) + formatString(postOrderTraversal(parentNode.getRight()), false) + parentNode.getVal().toString();
}

DATACLASS(TreeNode<T>(-T val, -TreeNode<T>left=null, -TreeNode<T>right=null, [-TreeNode<T> parent = null]), +val, +parent, +left, +right){
    private static String TREE_FORMAT = "TreeNode{val=%s, left=%s, right=%s, parent=%s}";
    public boolean isLeftChild () {
        return parent != null && parent.getLeft() == this;
    }
    public boolean isRightChild () {
        return parent != null && parent.getRight() == this;
    }
    @Override
    public String toString() {
        return String.format(TREE_FORMAT, val, left, right, parent==null?"":parent.getVal());
    }
}

public static <T extends Comparable<T>> int binarySearch(T[] array, T key) {
        int left = 0;
        int right = array.length - 1;
        int index = -1;
        int found = false;

        while (left <= right) {
            int mid = left + (right - left) / 2; // Avoids overflow
            int cmp = key.compareTo(array[mid]);

            if (cmp == 0) {
                found = true;
                index = mid;
            } else if (cmp < 0) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return index;
    }

