private Optional<TreeNode<T>> searchInSortedTree(TreeNode<T> rootNode, T value) {
    TreeNode<T> currentTreeNode = rootNode;
    TreeNode<T> foundTreeNode = null;
    boolean notfinished = true;
    while (notfinished){
        if (value.compareTo(currentTreeNode.getVal()) < 0) {
            if (currentTreeNode.getLeft() == null){
                foundTreeNode = currentTreeNode;
                notfinished = false;
            } else {
                currentTreeNode = currentTreeNode.getLeft();
            }
            }
        else if (value.compareTo(currentTreeNode.getVal()) > 0) {
            if (currentTreeNode.getRight() == null){
                foundTreeNode = currentTreeNode;
                notfinished = false;
            } else {
                currentTreeNode = currentTreeNode.getRight();
            }
        } else {
            foundTreeNode = currentTreeNode;
            notfinished = false;
        }
    }
    return Optional.of(foundTreeNode);
}

public Optional<TreeNode<T>> findInSortedTree(T value) {
    Optional<TreeNode<T>> foundTreeNode = searchInSortedTree(getRoot(), value);
    if (foundTreeNode.isPresent() && value.compareTo(foundTreeNode.get().getVal()) == 0) {
        return foundTreeNode;
    }
    return Optional.empty();
}

public void insertIntoSortedTree(T value) {
    Optional<TreeNode<T>> parentTreeNodeOptional = searchInSortedTree(getRoot(), value);
    if (parentTreeNodeOptional.isEmpty()) {
        setRoot(new TreeNode<>(value));
    } else {
        TreeNode<T> parentTreeNode = parentTreeNodeOptional.get();
        TreeNode<T> newNode = new TreeNode<>(value);
        if (value.compareTo(parentTreeNode.getVal()) < 0) {
            parentTreeNode.setLeft(newNode);
        } else if (value.compareTo(parentTreeNode.getVal()) > 0){
            parentTreeNode.setRight(newNode);
        }
    }
}

public void deleteFromSortedTree(T value) {
    Optional<TreeNode<T>> treeNodeOptional = findInSortedTree(value);
    if (treeNodeOptional.isEmpty()) {
        return;
    }
    TreeNode<T> treeNode = treeNodeOptional.get();

    if (treeNode.getLeft() == null && treeNode.getRight() == null){
        replaceTreeNode(treeNode, null);
    }
    else if (treeNode.getLeft() != null && treeNode.getRight() == null){
        replaceTreeNode(treeNode, treeNode.getLeft());
        treeNode.deleteLeft();
    }
    else if (treeNode.getLeft() == null && treeNode.getRight() != null){
        replaceTreeNode(treeNode, treeNode.getRight());
        treeNode.deleteRight();
    }
    else if (treeNode.getLeft() != null && treeNode.getRight() != null){
        TreeNode<T> replaceTreeNode = treeNode.getLeft();
        while (replaceTreeNode.getRight() != null) {
            replaceTreeNode = replaceTreeNode.getRight();
        }
        if (replaceTreeNode.getLeft() != null){
            TreeNode<T> subReplaceTreeNode = replaceTreeNode.getLeft();
            replaceTreeNode.deleteLeft();
            replaceTreeNode.getParent().setRight(subReplaceTreeNode);
        }
        TreeNode<T> replaceTreeNodeParent = replaceTreeNode.getParent();
        if (replaceTreeNode.isLeftChild()) {
            replaceTreeNodeParent.deleteLeft();
        }
        else if (replaceTreeNode.isRightChild()){
            replaceTreeNodeParent.deleteRight();
        }
        treeNode.setVal(replaceTreeNode.getVal());
    }
}

private void replaceTreeNode (TreeNode<T> treeNode, TreeNode<T> replaceTreeNode) {
    TreeNode<T> parentTreeNode = treeNode.getParent();
    if (parentTreeNode == null) {
        setRoot(replaceTreeNode);
    }
    else{
        if (treeNode.isLeftChild()) {
            parentTreeNode.setLeft(replaceTreeNode);
        }
        else if (treeNode.isRightChild()){
            parentTreeNode.setRight(replaceTreeNode);
        }
    }
}

private static final int ROOT_NODE_INDEX = 0;
private ArrayList<T> heap;
private BiFunction <T, T, Integer> comparator;

public Heap(Integer heapSize, BiFunction<T, T, Integer> comparator){
    this.comparator = comparator;
    heap = new ArrayList<>(heapSize);
}

private void filterDown(int currentIndex){
    int heapSize = heap.size();
    if (heapSize <= 1){
        return;
    }
    boolean continueFilterDown = true;
    while (continueFilterDown){
        continueFilterDown = false;
        int leftChildIndex = 2 * currentIndex + 1;
        int rightChildIndex = 2 * currentIndex + 2;
        T current = heap.get(currentIndex);
        T leftChild = heap.get(leftChildIndex);
        T rightChild = rightChildIndex < heapSize ? heap.get(rightChildIndex) : null;
        int smallestChildIndex;
        T smallestChild;
        if (rightChild == null){
            smallestChildIndex = leftChildIndex;
            smallestChild = leftChild;
        }
        else{
            if (comparator.apply(leftChild, rightChild) > 0){
                smallestChildIndex = rightChildIndex;
                smallestChild = rightChild;
            }
            else{
                smallestChildIndex = leftChildIndex;
                smallestChild = leftChild;
            }
        }
        if (comparator.apply(current, smallestChild) > 0){
            heap.set(currentIndex, smallestChild);
            heap.set(smallestChildIndex, current);
            currentIndex = smallestChildIndex;
            continueFilterDown = 2 * currentIndex + 1 < heapSize;
        }
    }
}

private void filterUp(int currentIndex){
    T current = heap.get(currentIndex);
    int parentIndex = (currentIndex - 1) / 2;
    T parent = heap.get(parentIndex);
    while (currentIndex != parentIndex && comparator.apply(current, parent) < 0){
        heap.set(currentIndex, parent);
        heap.set(parentIndex, current);
        currentIndex = parentIndex;
        current = heap.get(currentIndex);
        parentIndex = (currentIndex - 1) / 2;
        parent = heap.get(parentIndex);
    }
}

public T getRoot(){
    return heap.isEmpty() ? null : heap.get(ROOT_NODE_INDEX);
}
public void insert(T value){
    int insertionIndex = heap.size();
    heap.add(value);
    filterUp(insertionIndex);
}
public void deleteRoot(){
    T lastNode = heap.removeLast();
    if (heap.isEmpty()) return;
    heap.set(ROOT_NODE_INDEX, lastNode);
    filterDown(ROOT_NODE_INDEX);
}

public Heap(List<T> list, BiFunction<T, T, Integer> comparator){
    this.comparator = comparator;
    int heapSize = list.size();
    heap = new ArrayList<>(heapSize);
    for (T value: list){
        heap.add(value);
    }

    for (int i = heapSize / 2 - 1; i >= 0; i--){
        filterDown(i);
    }
}

public String toString(){
    StringBuilder stringBuilder = new StringBuilder();
    int index = 0;
    int count = 1;
    while (index < heap.size()){
        for (int i = index; i < index + count && i < heap.size(); i++){
            stringBuilder.append(heap.get(i) + " ");
        }
        stringBuilder.append('\n');
        index += count;
        count *= 2;
    }
    return stringBuilder.toString();
}

public static void sort (int[] sequence){
    int e = 0;
    int holePos = 0;
    for (int pos = 1; pos < sequence.length; pos++){
        e = sequence[pos];
        holePos = pos;
        while (holePos > 0 && {{e < sequence[holePos - 1]}}){
            sequence[holePos] = sequence[holePos - 1];
            holePos--;
        }
        sequence[holePos] = e;
        System.out.println (java.util.Arrays.toString (sequence));
    }
}

public static void sort (String[] sequence){
    int lastPos = sequence.length - 1;
    int maxPos = 0;
    String e = "";
    for (int pos = 0; pos < lastPos; pos++){
        maxPos = pos;
        for (int p = pos + 1; p <= lastPos; p++)
            if (sequence[p].compareToIgnoreCase (sequence[maxPos]) < 0)
                maxPos = p;
            if (maxPos != pos){
                e = sequence[pos];
                sequence[pos] = sequence[maxPos];
                sequence[maxPos] = e;
            }
        System.out.println (java.util.Arrays.toString (sequence));
    }
}

public static void sort(int[] sequence) {
    int lastPos = sequence.length - 1;
    int minPos;
    int temp;

    for (int pos = lastPos; pos > 0; pos--) {

        // Find the smallest value in 0..pos
        minPos = 0;
        for (int p = 1; p <= pos; p++) {
            if (sequence[p] < sequence[minPos]) {
                minPos = p;
            }
        }

        // Swap smallest with element at current end (pos)
        if (minPos != pos) {
            temp = sequence[pos];
            sequence[pos] = sequence[minPos];
            sequence[minPos] = temp;
        }

        System.out.println(java.util.Arrays.toString(sequence));
    }
}

public static <T> List<T> bubbleSort(List<T> list, BiFunction<T, T, Integer> comparator){
    T first;
    T second;
    for (int endIndex = 0; endIndex < list.size() - 1; endIndex ++){
        for (int startIndex = list.size() - 1; startIndex > endIndex; startIndex--){
            first = list.get(startIndex);
            second = list.get(startIndex - 1);
            if (comparator.apply(first, second) < 0){
                list.set(startIndex, second);
                list.set(startIndex - 1, first);
            }
        }
    }
    return list;
}

public static <T> List<T> exchangeSort(List<T> list, BiFunction<T, T, Integer> comparator){
    T anchorValue;
    T compareValue;
    for (int anchorIndex = 0; anchorIndex < list.size() - 1; anchorIndex ++){
        for (int compareIndex = anchorIndex + 1; compareIndex < list.size(); compareIndex ++){
            anchorValue = list.get(anchorIndex);
            compareValue = list.get(compareIndex);
            if (comparator.apply(anchorValue, compareValue) > 0){
                list.set(anchorIndex, compareValue);
                list.set(compareIndex, anchorValue);
            }
        }
    }
    return list;
}

private static <T> List<T> mergeSortedLists(List<T> list1, List<T> list2, BiFunction<T, T, Integer> comparator){
    int list1size = list1.size();
    int list2size = list2.size();
    List<T> list = new ArrayList<>(list1size + list2size);
    int index1 = 0;
    int index2 = 0;
    while (index1 < list1size && index2 < list2size){
        T value1 = list1.get(index1);
        T value2 = list2.get(index2);
        if (comparator.apply(value1, value2) > 0){
            list.add(value2);
            index2++;
        }
        else{
            list.add(value1);
            index1++;
        }
    }
    while (index1 < list1size) {
        list.add(list1.get(index1));
        index1++;
    }
    while (index2 < list2size) {
        list.add(list2.get(index2));
        index2++;
    }
    return list;
}

public static <T> List<T> mergeSort(List<T> list, BiFunction<T, T, Integer> comparator){
    int size = list.size();
    if (size <= 1){
        return list;
    }
    else if (size == 2){
        T value0 = list.get(0);
        T value1 = list.get(1);
        if (comparator.apply(value0, value1) > 0){
            list.set(0, value1);
            list.set(1, value0);
        }
        return list;
    }
    int halfSize = size / 2;
    List<T> list1 = list.subList(0, halfSize);
    List<T> list2 = list.subList(halfSize, size);
    return mergeSortedLists(mergeSort(list1, comparator), mergeSort(list2, comparator), comparator);
}

public static int[] radixSort(int[] array){
    int size = array.length;
    int maxValue = MAX(array);
    int[] output = new int[size];
    int[] count = new int[10];
    for (int exp = 1; maxValue / exp > 0; exp *= 10){
        for (int i = 0; i < count.length; i++){
            count[i] = 0;
        }
        for (int number : array){
            int digit = (number / exp) % 10;
            count[digit]++;
        }
        for (int i = 1; i < 10; i++){
            count[i] += count[i-1];
        }
        for (int i = size - 1; i >= 0; i--){
            int digit = (array[i] / exp) % 10;
            output[count[digit] - 1] = array[i];
            count[digit]--;
        }
        System.arraycopy(output, 0, array, 0, size);
    }
    return array;
}

private static int sibling(int i) {
    return (i % 2 == 0) ? i - 1 : i + 1;
}

private static <T> T get(ArrayList<T> a, int i) {
    return (i < a.size()) ? a.get(i) : null;
}

public static int nextPowerOfTwo(int x) {
    if (x <= 0) return 1;
    x--;
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    return x + 1;
}

private static <T> void chooseWinner(ArrayList<T> tree, ArrayList<Integer> idx, int parent, int leftIndex, int rightIndex, BiFunction<T,T,Integer> cmp, boolean useChildIndexArrays) {
    T left  = get(tree, leftIndex);
    T right = get(tree, rightIndex);

    if (left != null && right != null) {
        if (cmp.apply(left, right) <= 0) {
            tree.set(parent, left);
            idx.set(parent, useChildIndexArrays ? idx.get(leftIndex) : leftIndex);
        } else {
            tree.set(parent, right);
            idx.set(parent, useChildIndexArrays ? idx.get(rightIndex) : rightIndex);
        }
    }
    else if (left != null) {
        tree.set(parent, left);
        idx.set(parent, useChildIndexArrays ? idx.get(leftIndex) : leftIndex);
    }
    else if (right != null) {
        tree.set(parent, right);
        idx.set(parent, useChildIndexArrays ? idx.get(rightIndex) : rightIndex);
    }
    else {
        tree.set(parent, null);
        idx.set(parent, 0);
    }
}

public static <T> ArrayList<T> tournamentSort(List<T> array, BiFunction<T, T, Integer> comparator) {
    int fitArraySize = nextPowerOfTwo(array.size());
    int L = fitArraySize - 1;       // number of parents
    int totalSize = fitArraySize + L;
    ArrayList<T> tree = new ArrayList<>(totalSize);
    ArrayList<Integer> idx = new ArrayList<>(L);

    // Fill parents with null
    for (int i = 0; i < L; i++) tree.add(null);
    // Fill leaves with input (rest remain null)
    for (int i = 0; i < array.size(); i++) tree.add(array.get(i));
    // index array default
    for (int i = 0; i < L; i++) idx.add(0);

    // Initial tournament from leaves up
    int leafStart = L;
    for (int i = totalSize - 1; i > leafStart - 1; i -= 2) {
        int parent = (i - 1) / 2;
        chooseWinner(tree, idx, parent, i - 1, i, comparator, false);
    }
    for (int i = leafStart - 1; i > 0; i -= 2) {
        int parent = (i - 1) / 2;
        chooseWinner(tree, idx, parent, i - 1, i, comparator, true);
    }

    // Extract sorted results
    ArrayList<T> result = new ArrayList<>();
    while (idx.get(0) != 0) {
        int lowestIndex = idx.get(0);
        tree.set(lowestIndex, null); // Remove winner leaf

        // Replace parent with sibling
        int sib = sibling(lowestIndex);
        int parent = (lowestIndex - 1) / 2;
        tree.set(parent, get(tree, sib));
        idx.set(parent, sib);

        // Bubble replacement upward
        int curr = parent;
        while (curr > 0) {
            int parent2 = (curr - 1) / 2;
            int sib2 = sibling(curr);
            chooseWinner(tree, idx, parent2, curr, sib2, comparator, true);
            curr = parent2;
        }

        T lowest = tree.get(0);
        if (lowest != null) result.add(lowest);
    }

    return result;
}
